mapper.select:
SELECT sr.id, sr.supplier_return_id AS supplierReturnId, sr.supplier_return_code AS supplierReturnCode, sr.warehouse_node_id AS warehouseNodeId, wn.node_name AS warehouseNodeName, sr.supplier_id AS supplierId, s.supplier_name AS supplierName, sr.return_status AS returnStatus, sr.return_type AS returnType, sr.apply_user_id AS applyUserId, sr.apply_time AS applyTime, sr.audit_user_id AS auditUserId, sr.audit_time AS auditTime, sr.audit_opinion AS auditOpinion, sr.remark, sr.create_time AS createTime FROM spd_supplier_return sr LEFT JOIN spd_org_node wn ON sr.warehouse_node_id = wn.node_id AND wn.del_flag = 0 LEFT JOIN spd_supplier s ON sr.supplier_id = s.supplier_id AND s.del_flag = 0 WHERE sr.del_flag = 0
AND sr.return_status = #{form.returnStatus}
AND sr.return_type = #{form.returnType}
AND sr.supplier_id = #{form.supplierId}
AND sr.supplier_return_code LIKE CONCAT('%', #{form.supplierReturnCode}, '%')
ORDER BY sr.create_time DESC
